import secrets

class HoneytokenTripwire:
 def __init__(self):
 self.active_canaries = set()

 def generate_token(self) -> str:
 token = f"CANARY_{secrets.token_hex(8).upper()}"
 self.active_canaries.add(token)
 return token

 def inspect_egress_payload(self, tool_name: str, payload: dict) -> bool:
 raw_str = str(payload)
 for canary in list(self.active_canaries):
 if canary in raw_str:
 raise RuntimeError(f"CRITICAL: Honeytoken leak in egress tool '{tool_name}'. Session severed.")
 return True

from dataclasses import dataclass
from typing import List, Dict, Any
import time

@dataclass
class AgentEvent:
 step_index: int
 action_type: str
 payload: Dict[str, Any]
 timestamp: float = time.time()

class EventSourcedAgentState:
 def __init__(self):
 self.event_stream: List[AgentEvent] = []

 def append_event(self, action_type: str, payload: Dict[str, Any]):
 event = AgentEvent(len(self.event_stream), action_type, payload)
 self.event_stream.append(event)

 def rollback_to_step(self, target_step: int):
 self.event_stream = self.event_stream[:target_step + 1]
